-- Consolidate private-message reports into the abuse case queue and preserve reporter reason.
create or replace function public.dm_report_message(p_message_id uuid,p_reason text default ''::text) returns uuid language plpgsql security definer set search_path=pg_catalog,public as $function$ declare v_user uuid:=auth.uid(); v_subject uuid; v_report_id uuid; v_reason text:=left(btrim(coalesce(p_reason,'')),3000); begin if v_user is null then raise exception 'Authentication required'; end if; if p_message_id is null then raise exception 'Message is required'; end if; if char_length(v_reason)=0 then raise exception 'A report reason is required'; end if; select case when m.sender_id=v_user then m.recipient_id else m.sender_id end into v_subject from public.private_messages m where m.id=p_message_id and (m.sender_id=v_user or m.recipient_id=v_user) limit 1; if not found then raise exception 'Message not found or not accessible'; end if; insert into public.spike_abuse_cases(reporter_id,subject_user_id,source,source_id,category,details,status,severity) values(v_user,v_subject,'message',p_message_id::text,'other',v_reason,'open',1) returning id into v_report_id; return v_report_id; end; $function$;
revoke all on function public.dm_report_message(uuid,text) from public; revoke all on function public.dm_report_message(uuid,text) from anon; grant execute on function public.dm_report_message(uuid,text) to authenticated;
